<?php $filters = isset($filters) ? $filters : array(); ?><form class="form-row mb-3" method="get"><div class="col-md-3 mb-2"><input class="form-control" name="q" placeholder="Cari perihal, tujuan, nomor" value="<?php echo html_escape($filters['q']); ?>"></div><div class="col-md-2 mb-2"><select class="form-control" name="status"><option value="">Semua status</option><?php foreach (array('Diajukan','Diproses Sekretaris','Sudah Diberi Nomor','Diteruskan ke Direktur','Ditandatangani','Didisposisikan','Selesai') as $status): ?><option <?php echo $filters['status'] === $status ? 'selected' : ''; ?>><?php echo $status; ?></option><?php endforeach; ?></select></div><div class="col-md-2 mb-2"><select class="form-control" name="jenis"><option value="">Semua jenis</option><option value="internal" <?php echo $filters['jenis'] === 'internal' ? 'selected' : ''; ?>>Internal</option><option value="eksternal" <?php echo $filters['jenis'] === 'eksternal' ? 'selected' : ''; ?>>Eksternal</option></select></div><div class="col-md-2 mb-2"><input type="date" class="form-control" name="mulai" value="<?php echo html_escape($filters['mulai']); ?>"></div><div class="col-md-2 mb-2"><input type="date" class="form-control" name="sampai" value="<?php echo html_escape($filters['sampai']); ?>"></div><div class="col-md-1 mb-2"><button class="btn btn-primary">Filter</button></div></form><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Nomor / Perihal</th><th>Jenis</th><th>Pemohon</th><th>Status</th><th>Update Terakhir</th><th>Aksi</th></tr></thead><tbody><?php if (!$surat): ?><tr><td colspan="6" class="text-center text-muted">Belum ada surat.</td></tr><?php endif; ?><?php foreach ($surat as $row): ?><tr><td><strong><?php echo html_escape($row->no_surat ?: 'Belum bernomor'); ?></strong><br><?php echo html_escape($row->perihal); ?><small class="d-block text-muted"><?php echo html_escape($row->tujuan); ?></small></td><td><?php echo ucfirst($row->jenis); ?></td><td><?php echo html_escape($row->pemohon); ?></td><td><span class="badge badge-<?php echo surat_status_class($row->status); ?>"><?php echo html_escape($row->status); ?></span></td><td><small><?php echo html_escape($row->last_update ?: $row->updated_at); ?><br><?php echo html_escape($row->last_update_by ?: '-'); ?></small></td><td><a class="btn btn-sm btn-outline-primary" href="<?php echo site_url('surat/detail/' . $row->id); ?>">Detail</a><?php if (isset($action) && $action): ?> <a class="btn btn-sm btn-primary" href="<?php echo site_url($action . '/' . $row->id); ?>">Proses</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
